#pragma once

// codol_edit: entity classes of Call of Duty Online 1.1.1.13.
//
// The table is generated by codol_edit/tools/codol_classgen from the entity strings of every map fastfile of
// the install ( src/class_catalog_data.inc, checked in ) - it lists what the shipped maps really use: each
// classname, how often it occurs, whether it is a point entity or carries a compiled brush model, the keys that
// were seen with example values, and the spawnflags values. A few facts that are certain are added by hand
// ( box sizes and colours of spawn points, lights .. ). The CoD4 .def files are not used.

#include <cstdint>
#include <span>
#include <string_view>

namespace codol::edit
{
	struct class_key
	{
		std::string_view name;
		int count = 0;									// entities of the class that have the key
		std::span<const std::string_view> examples;		// most frequent values first ( up to 4 )
	};

	struct class_spawnflags
	{
		int value = 0;
		int count = 0;
	};

	struct class_info
	{
		std::string_view name;
		int count = 0;				// entities over all maps
		int map_count = 0;			// maps that have at least one
		int point_count = 0;		// without a compiled model
		int brush_count = 0;		// with "model" "*N" ( brush model ) or "?N" ( trigger hull )
		std::span<const class_key> keys;				// most frequent first; "classname" is not listed
		std::span<const class_spawnflags> spawnflags;	// most frequent first

		// hand written
		bool has_box = false;		// mins / maxs / color are known; otherwise the defaults below
		float mins[3] = { -8, -8, -8 };
		float maxs[3] = { 8, 8, 8 };
		float color[3] = { 0.8f, 0.8f, 0.8f };
		std::string_view description;

		// what "create entity" should make: a point entity, or an entity around the selected brushes
		[[nodiscard]] bool is_point() const { return point_count >= brush_count; }
		[[nodiscard]] const class_key* find_key(std::string_view key) const;
	};

	class class_catalog
	{
	public:
		// the generated table of the 1.1.1.13 install
		static const class_catalog& c1();

		[[nodiscard]] std::span<const class_info> classes() const { return classes_; }	// sorted by name
		[[nodiscard]] const class_info* find(std::string_view classname) const;
		[[nodiscard]] int map_count() const { return map_count_; }						// fastfiles the table was built from

		// box of a point entity of that class, relative to its origin ( the default +-8 cube when unknown )
		void box(std::string_view classname, float mins[3], float maxs[3]) const;

	private:
		std::span<const class_info> classes_;
		int map_count_ = 0;
	};
}
